type AppRole = Role | 'GUEST';
type AuthGateRequest = { title: string; message: string; returnTo: string; intent?: string };

type AppContextValue = {
  data: Bootstrap & { user: any };
  role: AppRole;
  isAuthenticated: boolean;
  requireAuthentication: (request: AuthGateRequest) => void;
  guestCart: any[];
  addToGuestCart: (item: any) => void;
  removeFromGuestCart: (id: string) => void;
  language: string;
  translationBundle: TranslationBundle | null;
  translationLoading: boolean;
  setLanguage: (value: string) => void;
  dataSaver: boolean;
  setDataSaver: (value: boolean) => void;
  toast: (message: string, kind?: 'success' | 'error') => void;
  refresh: () => Promise<void>;
  markNotificationRead: (id: string) => Promise<void>;
  markAllNotificationsRead: () => Promise<void>;
  logout: () => Promise<void>;
};

const AppContext = createContext<AppContextValue | null>(null);
const useApp = () => useContext(AppContext)!;

