  const submit=async()=>{setSaving(true);try{const response=await api.adminModuleAction(module,record.id,{action:action.id,reason:reason||undefined,confirmation:confirmation||undefined,otp:otp||undefined});toast(response.message);completed();}catch(error){toast(error instanceof Error?error.message:'The action could not be completed.','error');}finally{setSaving(false);}};
